/** Proposed actual native interaction/menu/recipe/payment/callback boundaries. Runtime UNRUN. */
public final class BlueprintGameTests {
 private static final BlockPos P=new BlockPos(3,3,3);
 private static BlueprintEntity blueprint(GameTestHelper h){var pos=h.absolutePos(P);h.getLevel().setBlockAndUpdate(pos.north(),Blocks.STONE.defaultBlockState());var entity=new BlueprintEntity(h.getLevel(),pos,Direction.SOUTH,Direction.DOWN);h.assertTrue(entity.size()==1&&entity.survives()&&h.getLevel().addFreshEntity(entity),"Genuine source fitting selects one actually supported native section");return entity;}
 private static NativeSurvivalTestPlayer player(GameTestHelper h,BlueprintEntity blueprint){var joined=NativeSurvivalTestPlayer.join(h,blueprint.position().add(0,0,2));joined.player().getInventory().clearContent();return joined;}
 private static void fixtureRecipe(BlueprintEntity blueprint){var ghosts=new SimpleContainer(11);ghosts.setItem(0,new ItemStack(Items.MILK_BUCKET));ghosts.setItem(9,new ItemStack(BlueprintTestFixtures.OUTPUT));blueprint.getSection(0).save(ghosts,false);}
 private static int count(Player player,Item item){return player.getInventory().countItem(item);}
 private static void craftFixture(GameTestHelper h,NativeSurvivalTestPlayer joined,BlueprintEntity blueprint,BlueprintTestFixtures.Mode mode,BlueprintTestFixtures.NativeRefusal error,BlueprintTestFixtures.Observation observation){BlueprintTestFixtures.with(new BlueprintTestFixtures.Scope(joined.player(),blueprint.getSection(0),mode,error,observation),()->joined.player().interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO));}
 private static ItemStack named(Item item,int count){var stack=new ItemStack(item,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original finite blueprint stock"));return stack;}
 @GameTest public void wallFloorCeilingUseActualNativeDirectionBoundsAndPersistentSectionData(GameTestHelper h){var pos=h.absolutePos(P);for(var facing:Direction.values()){h.getLevel().setBlockAndUpdate(pos.relative(facing.getOpposite()),Blocks.STONE.defaultBlockState());var entity=new BlueprintEntity(h.getLevel(),pos,facing,facing.getAxis().isHorizontal()?Direction.DOWN:Direction.EAST);h.assertTrue(entity.size()==1&&entity.getDirection()==facing&&entity.survives()&&h.getLevel().addFreshEntity(entity),"Real source wall/floor/ceiling placement fits only actual supported native blocks: "+facing);var ghosts=new SimpleContainer(11);ghosts.setItem(9,named(Items.APPLE,1));entity.getSection(0).save(ghosts,true);var output=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());h.assertTrue(entity.save(output),"Actual blueprint persists through native ValueOutput");var loaded=net.minecraft.world.entity.EntityType.loadEntityRecursive(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),output.buildResult()),h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.LOAD,actual->actual);h.assertTrue(loaded instanceof BlueprintEntity blueprint&&blueprint.getDirection()==facing&&blueprint.size()==1&&blueprint.getBoundingBox().equals(entity.getBoundingBox())&&blueprint.getSection(0).inferredIcon()&&ItemStack.matches(blueprint.getSection(0).getItems().getItem(9),named(Items.APPLE,1))&&h.getLevel().getEntity(entity.getUUID())==entity,"Native detached save decode preserves actual source geometry and ghost metadata without another admitted owner: "+facing);entity.discard();h.getLevel().setBlockAndUpdate(pos.relative(facing.getOpposite()),Blocks.AIR.defaultBlockState());}h.succeed();}
 @GameTest public void genuineOffhandInputPaysOnceAndPreservesFullNativeCraftedCargoAndRemainder(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();var milk=named(Items.MILK_BUCKET,1);player.setItemInHand(InteractionHand.OFF_HAND,milk);var observation=new BlueprintTestFixtures.Observation();craftFixture(h,joined,blueprint,BlueprintTestFixtures.Mode.NORMAL,null,observation);var expected=new ItemStack(BlueprintTestFixtures.OUTPUT,4);BlueprintTestFixtures.decorate(expected);h.assertTrue(observation.calls==1&&count(player,Items.MILK_BUCKET)==0&&count(player,Items.BUCKET)==1&&count(player,BlueprintTestFixtures.OUTPUT)==4,"Actual source selection scans real offhand and native crafting remainder returns once");h.assertTrue(java.util.stream.IntStream.range(0,player.getInventory().getContainerSize()).anyMatch(slot->ItemStack.matches(player.getInventory().getItem(slot),expected)),"Actual post-hook full component/cargo variant reaches one genuine finite destination");}h.succeed();}
 @GameTest public void nativeSneakCraftingStopsAtSixtyFourAndKeepsUnselectedOriginalVariant(GameTestHelper h){var blueprint=blueprint(h);var ghosts=new SimpleContainer(11);ghosts.setItem(0,new ItemStack(Items.OAK_PLANKS));ghosts.setItem(3,new ItemStack(Items.OAK_PLANKS));ghosts.setItem(9,new ItemStack(Items.STICK));blueprint.getSection(0).save(ghosts,false);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,named(Items.OAK_PLANKS,64));var untouched=named(Items.OAK_PLANKS,64);player.getInventory().setItem(9,untouched);player.setShiftKeyDown(true);player.interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO);h.assertTrue(count(player,Items.STICK)==64&&player.getInventory().getItem(0).getCount()==32&&player.getInventory().getItem(9)==untouched&&untouched.getCount()==64,"Source batch pays32 actual first-slot plank items for64 genuine sticks, preserving later physical owner and original components");}h.succeed();}
 @GameTest public void missingIngredientAndInvalidNativeRecipeCannotDebitAnyOriginalOwner(GameTestHelper h){var blueprint=blueprint(h);var ghosts=new SimpleContainer(11);ghosts.setItem(0,new ItemStack(Items.OAK_PLANKS));ghosts.setItem(3,new ItemStack(Items.DIAMOND));ghosts.setItem(9,new ItemStack(Items.STICK));blueprint.getSection(0).save(ghosts,false);try(var joined=player(h,blueprint)){var player=joined.player();var original=named(Items.OAK_PLANKS,3);player.getInventory().setItem(0,original);player.interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO);h.assertTrue(player.getInventory().getItem(0)==original&&original.getCount()==3&&count(player,Items.STICK)==0,"Failed real nine-slot ingredient reservation never mutates selected input");var diamond=named(Items.DIAMOND,2);player.getInventory().setItem(1,diamond);player.interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO);h.assertTrue(player.getInventory().getItem(0)==original&&original.getCount()==3&&player.getInventory().getItem(1)==diamond&&diamond.getCount()==2&&count(player,Items.STICK)==0,"A complete invalid actual native CraftingInput cannot debit either original slot");}h.succeed();}
 @GameTest public void sourceTagFilterUsesActualPublicNativeIngredientAndFiniteMixedInputs(GameTestHelper h){var blueprint=blueprint(h);var ops=h.getLevel().registryAccess().createSerializationContext(JsonOps.INSTANCE);var ingredient=Ingredient.CODEC.parse(ops,JsonParser.parseString("\"#minecraft:planks\"")).getOrThrow();var filter=BlueprintIngredients.convert(h.getLevel(),ingredient);h.assertTrue(filter.is(AllItems.ATTRIBUTE_FILTER)&&FilterItemStack.of(filter).test(h.getLevel(),new ItemStack(Items.OAK_PLANKS))&&!FilterItemStack.of(filter).test(h.getLevel(),new ItemStack(Items.DIRT)),"Actual named tag becomes source attribute filter rather than flattened/dummy holder data");var ghosts=new SimpleContainer(11);ghosts.setItem(0,filter);ghosts.setItem(3,filter.copy());ghosts.setItem(9,new ItemStack(Items.STICK));blueprint.getSection(0).save(ghosts,false);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,named(Items.OAK_PLANKS,1));player.getInventory().setItem(1,named(Items.BIRCH_PLANKS,1));player.interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO);h.assertTrue(count(player,Items.OAK_PLANKS)==0&&count(player,Items.BIRCH_PLANKS)==0&&count(player,Items.STICK)==4,"Actual source filter reserves two different real tag variants through one native payment transaction");}h.succeed();}
 @GameTest public void genuineNativeMenuGhostClicksNeverExtractOrDuplicatePhysicalStock(GameTestHelper h){var blueprint=blueprint(h);try(var joined=player(h,blueprint)){var player=joined.player();player.openMenu(blueprint.getSection(0));var menu=(BlueprintMenu)player.containerMenu;var original=named(Items.DIAMOND,7);player.getInventory().setItem(0,original);menu.quickMoveStack(player,27);menu.quickMoveStack(player,27);h.assertTrue(player.getInventory().getItem(0)==original&&original.getCount()==7&&menu.ghostItems().getItem(0).getCount()==1&&menu.ghostItems().getItem(1).getCount()==1,"Source allows repeated genuine ghost samples without moving either finite physical item");menu.setCarried(named(Items.APPLE,3));var carried=menu.getCarried();menu.clicked(38,0,ContainerInput.PICKUP,player);menu.clicked(38,0,ContainerInput.THROW,player);h.assertTrue(menu.getCarried()==carried&&carried.getCount()==3&&menu.ghostItems().getItem(2).getCount()==1&&count(player,Items.APPLE)==0,"Actual fake ghost slot copies metadata and rejects physical THROW extraction");menu.setCarried(ItemStack.EMPTY);player.closeContainer();h.assertTrue(count(player,Items.DIAMOND)==7,"Native menu close retains original finite player stock once");}h.succeed();}
 @GameTest public void sourceInferredAndManualIconsPersistThroughGenuineSectionMetadata(GameTestHelper h){var blueprint=blueprint(h);try(var joined=player(h,blueprint)){var player=joined.player();player.openMenu(blueprint.getSection(0));var menu=(BlueprintMenu)player.containerMenu;menu.setCarried(new ItemStack(Items.OAK_PLANKS));menu.clicked(36,0,ContainerInput.PICKUP,player);menu.clicked(39,0,ContainerInput.PICKUP,player);h.assertTrue(menu.inferredIcon()&&menu.ghostItems().getItem(9).is(Items.STICK)&&blueprint.getSection(0).inferredIcon(),"Genuine server RecipeManager infers output and stores section inference, synchronized through ContainerData");menu.setCarried(new ItemStack(Items.DIAMOND));menu.clicked(45,0,ContainerInput.PICKUP,player);h.assertTrue(!menu.inferredIcon()&&blueprint.getSection(0).getItems().getItem(9).is(Items.DIAMOND),"An actual manually assigned ghost icon clears inference without clearing any real component");menu.setCarried(ItemStack.EMPTY);player.closeContainer();}h.succeed();}
 @GameTest public void realNativeCraftedErrorPreservesCausePaidInputsAndCurrentOutputCargo(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));var error=new BlueprintTestFixtures.NativeRefusal();var observation=new BlueprintTestFixtures.Observation();boolean caught=false;try{craftFixture(h,joined,blueprint,BlueprintTestFixtures.Mode.ERROR,error,observation);}catch(BlueprintTestFixtures.NativeRefusal actual){caught=actual==error;}var expected=new ItemStack(BlueprintTestFixtures.OUTPUT,4);BlueprintTestFixtures.decorate(expected);h.assertTrue(caught&&observation.calls==1&&count(player,Items.MILK_BUCKET)==0&&count(player,BlueprintTestFixtures.OUTPUT)==4&&count(player,Items.BUCKET)==1,"Exact native error propagates after one real payment, current output and the preowned genuine bucket remainder each transfer once");h.assertTrue(java.util.stream.IntStream.range(0,player.getInventory().getContainerSize()).anyMatch(slot->ItemStack.matches(player.getInventory().getItem(slot),expected)),"Native late-throw result components/cargo survive; no pre-hook variant was published");}h.succeed();}
 @GameTest public void nativeCraftedHookCanEmptyOutputWithoutAnySnapshotResurrection(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));var observation=new BlueprintTestFixtures.Observation();craftFixture(h,joined,blueprint,BlueprintTestFixtures.Mode.EMPTY,null,observation);h.assertTrue(observation.result.isEmpty()&&count(player,Items.MILK_BUCKET)==0&&count(player,BlueprintTestFixtures.OUTPUT)==0&&count(player,Items.BUCKET)==1,"Actual source hook empties its produced stack; genuine remainder is delivered and output is never rebuilt from a snapshot");}h.succeed();}
 @GameTest public void nativeCraftedHookTransferKeepsExactActualOwnerAndNoSecondDelivery(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));var observation=new BlueprintTestFixtures.Observation();craftFixture(h,joined,blueprint,BlueprintTestFixtures.Mode.TRANSFER,null,observation);h.assertTrue(player.getInventory().getItem(20)==observation.result&&count(player,BlueprintTestFixtures.OUTPUT)==4&&count(player,Items.MILK_BUCKET)==0&&count(player,Items.BUCKET)==1,"Actual native crafted callback hands the same result to a real inventory slot; receipt relinquishes and cannot deliver twice");}h.succeed();}
 @GameTest public void actualNativeCraftedReentryCannotPayTheSameBlueprintTwice(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));player.getInventory().setItem(1,new ItemStack(Items.MILK_BUCKET));var observation=new BlueprintTestFixtures.Observation();craftFixture(h,joined,blueprint,BlueprintTestFixtures.Mode.RECURSE,null,observation);h.assertTrue(observation.calls==1&&observation.recursiveCrafts==0&&count(player,Items.MILK_BUCKET)==1&&count(player,BlueprintTestFixtures.OUTPUT)==4,"Thread-bound exact native actor guard rejects callback reentry before another actual payment");}h.succeed();}
 @GameTest public void authoritativePreviewDoesNotDebitOrRunActualNativeCraftedHooks(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);try(var joined=player(h,blueprint)){var player=joined.player();var first=named(Items.MILK_BUCKET,1);var second=named(Items.MILK_BUCKET,1);player.getInventory().setItem(0,first);player.getInventory().setItem(1,second);var preview=BlueprintCrafting.preview(player,blueprint.getSection(0),true);h.assertTrue(preview!=null&&preview.craftable()&&preview.result().getCount()==8&&preview.available().size()==2&&preview.missing().isEmpty(),"Actual server native recipes build source sneak preview from finite observations without recycling virtual results/remainders");h.assertTrue(player.getInventory().getItem(0)==first&&player.getInventory().getItem(1)==second&&first.getCount()==1&&second.getCount()==1&&count(player,BlueprintTestFixtures.OUTPUT)==0&&count(player,Items.BUCKET)==0,"Preview retains both exact native original owners and never invokes the unarmed crafted callback");}h.succeed();}
 @GameTest public void realFakePlayerRemovedEntityAndDistantActorCannotCraft(GameTestHelper h){var blueprint=blueprint(h);fixtureRecipe(blueprint);var fake=FakePlayer.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"blueprint_fixture"));fake.getInventory().clearContent();fake.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));h.assertTrue(BlueprintCrafting.craft(fake,blueprint.getSection(0),false)==0&&count(fake,Items.MILK_BUCKET)==1,"Genuine Fabric FakePlayer cannot use source blueprint crafting");try(var joined=player(h,blueprint)){var player=joined.player();var original=named(Items.MILK_BUCKET,1);player.getInventory().setItem(0,original);player.setPos(blueprint.position().add(20,0,0));h.assertTrue(BlueprintCrafting.craft(player,blueprint.getSection(0),false)==0&&player.getInventory().getItem(0)==original,"Actual range rejects payment");player.setPos(blueprint.position().add(0,0,2));blueprint.discard();h.assertTrue(BlueprintCrafting.craft(player,blueprint.getSection(0),false)==0&&player.getInventory().getItem(0)==original&&original.getCount()==1,"Removed actual entity identity cannot be replaced by stale section metadata");}h.succeed();}
 @GameTest public void completeRecipeAssignmentRequiresActualMenuEntityAndServerRecipeIdentity(GameTestHelper h){var blueprint=blueprint(h);try(var joined=player(h,blueprint)){var player=joined.player();player.openMenu(blueprint.getSection(0));var menu=(BlueprintMenu)player.containerMenu;var id=Identifier.fromNamespaceAndPath("create_test","blueprint/native_output");var wrong=new BlueprintMenu.Opening(blueprint.getId(),UUID.randomUUID(),0);BlueprintPackets.assign(player,new BlueprintPackets.Assign(menu.containerId,wrong,id));h.assertTrue(menu.ghostItems().isEmpty(),"Forged actual entity UUID cannot change source ghosts");BlueprintPackets.assign(player,new BlueprintPackets.Assign(menu.containerId,menu.opening(),id));h.assertTrue(menu.ghostItems().getItem(0).is(Items.MILK_BUCKET)&&menu.ghostItems().getItem(9).is(BlueprintTestFixtures.OUTPUT)&&count(player,Items.MILK_BUCKET)==0&&count(player,BlueprintTestFixtures.OUTPUT)==0,"Only genuine server crafting recipe metadata populates actual current editor; recipe transfer creates no physical material");player.closeContainer();}h.succeed();}
}
